UPDATE lessons SET title='Year 3, Week 8, Lesson 4: Oral presentation skills', data=json_patch(data,'{"child_mission":"Plan a clear opening, grouped points and conclusion; speak audibly at a pace that gives listeners time to understand.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same strategy to an unfamiliar topic or audience, then compare the effect of two different choices.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nGive a 20-second opening for a talk about a favourite local place and state two points you will cover.\n\nFEEDBACK\nA clear opening names the topic and previews two relevant points: ''I''ll tell you where the lookout is and why birds gather there.''\n\nCHECK\nReading every word from a slide can reduce connection with listeners; eye contact need not mean staring at one person.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nPrepare and deliver a 60-90 second factual presentation about a NSW place or animal, using four cue cards maximum. Record an opening, two organised facts with an explanation, and a conclusion. Self-assess volume, pace, clarity and one improvement after rehearsal.\n\nWrite a short reflection describing one specific revision you made and why.","interactive_activities":null,"learning_area":"English","learning_intention":"Plan a clear opening, grouped points and conclusion; speak audibly at a pace that gives listeners time to understand.","lesson_number":4,"lesson_role":"Speaking and handwriting","materials":["Paper or typed answer space","Pencil"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["EN2-OLC-01"],"parent_notes":"Parent: Marking guidance for the independent task: Prepare and deliver a 60-90 second factual presentation about a NSW place or animal, using four cue cards maximum. Record an opening, two organised facts with an explanation, and a conclusion. Self-assess volume, pace, c Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: original example using opening on new material; names a specific word, source or choice and explains its effect.\n\nParent: Written model 2: Sample error: Reading every word from a slide can reduce connection with listeners;. Correction: A clear opening names the topic and previews two relevant points: ''I''ll tell you where the lookout is and why birds. Why it helps the audience is stated.\n\nParent: Likely misconception: Reading every word from a slide can reduce connection with listeners; eye contact need not mean staring at one person. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating opening on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with opening, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Accept original work about opening with a specific supporting detail. Reject copied model wording with no new material. / Accept a misconception, a correction, and a purpose-linked reason for opening. Reject corrections that do not change the inaccurate idea..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":1,"explanation":"This matches the taught method for opening. The other choices miss a key step or use a common mistake.","options":["A method that skips the key step taught in this lesson.","A clear opening names the topic and previews two relevant points: ''I''ll tell you where the lookout is and why birds","Reading every word from a slide can reduce connection with listeners;","A claim that names no evidence from the lesson material."],"question":"Give a 20-second opening for a talk about a favourite local place and state two points you will cover. Which response is most accurate?","type":"multiple_choice"},{"correct_index":2,"explanation":"This is the misconception to avoid for opening; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["A clear opening names the topic and previews two relevant points: ''I''ll tell you where the lookout is and why birds","Careful use of cue notes and explain why it matters with clear evidence.","Reading every word from a slide can reduce connection with listeners;","Plan a clear opening, grouped points and conclusion;"],"question":"Which statement is a common mistake when working with opening?","type":"multiple_choice"},{"correct_index":2,"explanation":"Understanding is shown by new evidence and a named cue notes and explain why it matters, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Reading every word from a slide can reduce connection with listeners;","Name cue notes and explain why it matters only, without linking it to opening.","Apply opening to new material and name the cue notes and explain why it matters used.","Repeat the worked example wording with no new evidence."],"question":"Which response best applies opening with new evidence?","type":"multiple_choice"},{"correct_index":2,"explanation":"The skill is shown by quoting or pointing to wording that carries opening. The other choices miss a key step or use a common mistake.","options":["Say the writing is good without naming any words.","Reading every word from a slide can reduce connection with listeners;","Point to exact words in the sentence that show opening and say what they do.","Ignore the sentence and invent a more exciting event."],"question":"Read: \"At dawn, Mina whispered to her goat as frost glittered on the fence.\" Which choice best uses opening from this lesson?","type":"multiple_choice"},{"correct_index":1,"explanation":"The correct statement applies the language skill with textual evidence. The other choices miss a key step or use a common mistake.","options":["Name cue notes and explain why it matters without linking it to any words in the text.","A clear opening names the topic and previews two relevant points: ''I''ll tell you where the lookout is and why birds","Reading every word from a slide can reduce connection with listeners;","Copy a model sentence from another story unchanged."],"question":"Which statement correctly applies the lesson idea about opening?","type":"multiple_choice"},{"correct_index":0,"explanation":"Start from a specific textual clue, then explain its effect. The other choices miss a key step or use a common mistake.","options":["Locate a specific word, phrase or structural clue before deciding.","Guess from the title alone with no textual clue.","Copy a model sentence from another story unchanged.","Lengthen the answer with adjectives while keeping the same idea."],"question":"In a new text, what should you do first to analyse cue notes and explain why it matters?","type":"multiple_choice"},{"correct_index":3,"explanation":"Repair means fixing meaning or evidence, not padding. The other choices miss a key step or use a common mistake.","options":["Add adjectives without fixing the wrong idea.","Make the answer longer while keeping the same mistake.","Delete the evidence that disagreed with your first guess.","Change the inaccurate idea or missing evidence, not only the length."],"question":"Which revision actually improves meaning for opening?","type":"multiple_choice"},{"correct_index":3,"explanation":"Accurate transfer needs fresh material with an explained language choice. The other choices miss a key step or use a common mistake.","options":["Retype the worked model as the final answer.","Change fonts and claim the work is new.","Reading every word from a slide can reduce connection with listeners;","Use a fresh sentence or text and explain one precise choice about opening."],"question":"Which response shows accurate use of opening on fresh material?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept original work about opening with a specific supporting detail. Reject copied model wording with no new material.","question":"Produce a fresh example demonstrating opening on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Sample: original example using opening on new material; names a specific word, source or choice and explains its effect.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception, a correction, and a purpose-linked reason for opening. Reject corrections that do not change the inaccurate idea.","question":"Name one likely error with opening, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Sample error: Reading every word from a slide can reduce connection with listeners;. Correction: A clear opening names the topic and previews two relevant points: ''I''ll tell you where the lookout is and why birds. Why it helps the audience is stated.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent task and reflection, with explanations where requested.","review_status":"unreviewed","seed_key":"s2-eng-y3-w08-l4","sort_activity":null,"source_note":"Proposed Stage 2 NESA alignment; verify content points before acceptance.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise opening.","Read the mission before you start writing or speaking.","Keep the audience and purpose in mind as you work."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your reason with the feedback.","Adjust anything that does not match the evidence."],"learn":["Study how the first demonstration is built.","Point to the wording that carries the meaning.","Then explain the choice without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore the example.","Prefer evidence over wording that merely sounds clever."],"submit":["Check that your response and reason are both present.","Proofread names, sequence and punctuation.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact word or action before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and underline one useful detail.","Say what that detail helps a reader understand.","A vague compliment is weaker than quoted evidence."],"teach2":["Compare a weak attempt with a stronger revision.","Change meaning or accuracy, not only length.","Name the mistake you are repairing."],"teach3":["Choose a fresh topic that still uses the same skill.","Explain one decision in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include an original response and a short reason.","Save work that shows the skill on new content."]},"subject":"English","success_criteria":["I can use opening with a specific example from this lesson.","I can identify cue notes and explain why it matters.","I can practise pace independently on a new prompt.","I can notice conclusion needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":1,"explanation":"Plan a clear opening, grouped points and conclusion; speak audibly at a pace that gives listeners time to understand.","options":["An answer copied without understanding.","Plan a clear opening, grouped points and conclusion;","A guess with no explanation.","A claim unrelated to the text."],"question":"Which choice best applies this lesson idea about opening with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nOpening: ''Today I will explain three ways mangroves help a coastline.'' Points: roots protect mud, animals find shelter, leaves manage salty conditions. Ending: ''Together these features make mangroves important habitats.'' Cue notes prompt me without becoming a script.\n\nTRY FIRST\nGive a 20-second opening for a talk about a favourite local place and state two points you will cover.\n\nFEEDBACK\nA clear opening names the topic and previews two relevant points: ''I''ll tell you where the lookout is and why birds gather there.''","explain":"Plan a clear opening, grouped points and conclusion; speak audibly at a pace that gives listeners time to understand.\n\nWHY IT MATTERS\nThis helps the learner make decisions based on specific language evidence, rather than guess or copy someone else. Keep the meaning accurate and explain the choice.\n\nHOW TO WORK\nRead the original example and locate the words or actions that support the idea. Before looking at the correction, make your own attempt using the exact question provided. Check your response against the feedback: did you address the same skill and show your reasoning? If a detail is uncertain, identify what would have to be checked. One deliberate, justified revision is more useful than making the answer longer.","icon":"📖","notice":"Reading every word from a slide can reduce connection with listeners; eye contact need not mean staring at one person. Correct the meaning, not just the appearance.","title":"Understand and model","visual":[{"alt":"Spoken opening preview beside short cue notes.","caption":"Cue notes prompt speech without becoming a full script.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Opening</text><text x=\"28\" y=\"78\">three ways mangroves help</text><text x=\"358\" y=\"42\">Cue notes</text><text x=\"358\" y=\"78\">roots; shelter; salt</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which detail matters most.","who":"pip"},{"text":"Name the exact words or actions that carry the meaning before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: Opening: ''Today I will explain three ways mangroves help a coastline.'' Points: roots protect mud, animals find shelter,  Then write your own attempt.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which detail matters most.\nJuno: Name the exact words or actions that carry the meaning before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: Opening: ''Today I will explain three ways mangroves help a coastline.'' Points: roots protect mud, animals find shelter,  Then write your own attempt."}}]},{"check":{"correct_index":1,"explanation":"Make your choice visible: select the exact detail in the model that demonstrates the skill, and describe what it does for a reader.","options":["An answer copied without understanding.","Make your choice visible: select the exact detail in the model that demonstrates the skill, and describe what it does","A guess with no explanation.","A claim unrelated to the text."],"question":"Which choice best applies this lesson idea about opening with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nOpening: ''Today I will explain three ways mangroves help a coastline.'' Points: roots protect mud, animals find shelter, leaves manage salty conditions. Ending: ''Together these features make mangroves important habitats.'' Cue notes prompt me without becoming a script. Think about how this word or relationship creates meaning.\n\nTRY FIRST\nUnderline or quote one precise detail in the model and explain its effect.\n\nFEEDBACK\nThe most useful evidence is a specific choice in the example, followed by an explanation of the effect on meaning.","explain":"Make your choice visible: select the exact detail in the model that demonstrates the skill, and describe what it does for a reader.\n\nWHY IT MATTERS\nThis helps the learner make decisions based on specific language evidence, rather than guess or copy someone else. Keep the meaning accurate and explain the choice.\n\nHOW TO WORK\nRead the original example and locate the words or actions that support the idea. Before looking at the correction, make your own attempt using the exact question provided. Check your response against the feedback: did you address the same skill and show your reasoning? If a detail is uncertain, identify what would have to be checked. One deliberate, justified revision is more useful than making the answer longer.","icon":"📖","notice":"Saying a choice is good without naming the actual detail does not show understanding. Correct the meaning, not just the appearance.","title":"Explain the evidence","visual":[{"alt":"Organised talk points leading to a clear conclusion.","caption":"Pace and clarity help listeners follow the structure.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Points</text><text x=\"28\" y=\"78\">two organised facts</text><text x=\"358\" y=\"42\">Ending</text><text x=\"358\" y=\"78\">important habitats</text></g></svg>"}]},{"check":{"correct_index":0,"explanation":"Use an intentionally incorrect attempt as a comparison.","options":["Use an intentionally incorrect attempt as a comparison.","A claim unrelated to the text.","An answer copied without understanding.","A guess with no explanation."],"question":"Which choice best applies this lesson idea about opening with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nReading every word from a slide can reduce connection with listeners; eye contact need not mean staring at one person. Here is a more productive model: Opening: ''Today I will explain three ways mangroves help a coastline.'' Points: roots protect mud, animals find shelter, leaves manage salty conditions. Ending: ''Together these features make mangroves important habitats.'' Cue notes prompt me without becoming a script.\n\nTRY FIRST\nDescribe why the warned-against approach would weaken your work, then write a corrected version.\n\nFEEDBACK\nA clear opening names the topic and previews two relevant points: ''I''ll tell you where the lookout is and why birds gather there.''","explain":"Use an intentionally incorrect attempt as a comparison. Name its specific error, then show how a revision fixes that error.\n\nWHY IT MATTERS\nThis helps the learner make decisions based on specific language evidence, rather than guess or copy someone else. Keep the meaning accurate and explain the choice.\n\nHOW TO WORK\nRead the original example and locate the words or actions that support the idea. Before looking at the correction, make your own attempt using the exact question provided. Check your response against the feedback: did you address the same skill and show your reasoning? If a detail is uncertain, identify what would have to be checked. One deliberate, justified revision is more useful than making the answer longer.","icon":"📖","notice":"A superficial change in length or appearance does not repair meaning. Reading every word from a slide can reduce connection with listeners; eye contact need not mean staring at one person. Correct the meaning, not just the appearance.","title":"Test a misconception"},{"check":{"correct_index":2,"explanation":"Use the method on a new topic, not a reworded copy of the example.","options":["A guess with no explanation.","A claim unrelated to the text.","Use the method on a new topic, not a reworded copy of the example.","An answer copied without understanding."],"question":"Which choice best applies this lesson idea about opening with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nPlan a clear opening, grouped points and conclusion; speak audibly at a pace that gives listeners time to understand. Now choose different people, facts or text to show you can transfer the idea.\n\nTRY FIRST\nMake one fresh example demonstrating the skill and explain your main choice.\n\nFEEDBACK\nThe new example should meet the same purpose as the model, but contain original material.","explain":"Use the method on a new topic, not a reworded copy of the example. Review the result for accuracy and reader clarity.\n\nWHY IT MATTERS\nThis helps the learner make decisions based on specific language evidence, rather than guess or copy someone else. Keep the meaning accurate and explain the choice.\n\nHOW TO WORK\nRead the original example and locate the words or actions that support the idea. Before looking at the correction, make your own attempt using the exact question provided. Check your response against the feedback: did you address the same skill and show your reasoning? If a detail is uncertain, identify what would have to be checked. One deliberate, justified revision is more useful than making the answer longer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to new content. Correct the meaning, not just the appearance.","title":"Transfer to an independent example"}],"title":"Year 3, Week 8, Lesson 4: Oral presentation skills","unit_number":2,"unit_title":"Information reports","week":8,"week_in_unit":3,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nOpening: ''Today I will explain three ways mangroves help a coastline.'' Points: roots protect mud, animals find shelter, leaves manage salty conditions. Ending: ''Together these features make mangroves important habitats.'' Cue notes prompt me without becoming a script.\n\nExplain what makes this example accurate and effective, identifying its specific wording.","worked_visuals":[{"alt":"Spoken opening preview beside short cue notes.","caption":"Cue notes prompt speech without becoming a full script.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Opening</text><text x=\"28\" y=\"78\">three ways mangroves help</text><text x=\"358\" y=\"42\">Cue notes</text><text x=\"358\" y=\"78\">roots; shelter; salt</text></g></svg>"},{"alt":"Organised talk points leading to a clear conclusion.","caption":"Pace and clarity help listeners follow the structure.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Points</text><text x=\"28\" y=\"78\">two organised facts</text><text x=\"358\" y=\"42\">Ending</text><text x=\"358\" y=\"78\">important habitats</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-eng-y3-w08-l4' AND family_id IS NULL;
